theory = (
 H("A", "Coping with money", "Xoay xở chuyện tiền bạc")
 + T([
    ("<b>bail out</b> / <b>run through</b>", "Freyda’s parents helped her with money after she spent a lot very quickly and couldn’t pay her fees.", "Bố mẹ Freyda cứu cô bằng tiền sau khi cô tiêu hết rất nhanh, không đủ nộp học phí."),
    ("<b>cough up</b> / <b>work off</b>", "(informal) They gave the money without complaining; she will reduce the debt by working in the holidays.", "(thân mật) Họ chi tiền không phàn nàn; cô sẽ đi làm dịp nghỉ để trả bớt nợ."),
    ("<b>gobble up</b> / <b>break into</b> / <b>put by</b>", "(informal) A phone bill uses a large part of someone’s salary, so they start using savings kept for the holidays.", "(thân mật) Hóa đơn điện thoại ngốn phần lớn lương, nên phải động vào tiền tiết kiệm để dành cho kỳ nghỉ."),
    ("<b>set back</b> / <b>clean out</b> / <b>square up</b>", "(informal) Robert’s trip cost €8,000 and left him with no money; he will pay Matthew back on payday.", "(thân mật) Chuyến đi của Robert tốn €8.000 và làm anh cháy túi; anh sẽ trả Matthew khi có lương."),
    ("<b>come into</b> / <b>roll in</b> / <b>rent out</b>", "Someone got money when a relative died, and with a bonus too, money is arriving in large amounts; they may buy a flat and let others pay to live in it.", "Một người được thừa kế tiền, lại có thưởng nên tiền về ào ào; họ tính mua căn hộ cho thuê."),
 ])
 + H("B", "Financial services", "Dịch vụ tài chính")
 + T([
    ("<b>carry forward</b>", "a bank includes unpaid amounts in next month’s payments", "ngân hàng chuyển khoản chưa trả sang tháng sau"),
    ("<b>plough back</b>", "put profits back into a small business to make it bigger or better", "tái đầu tư lợi nhuận vào doanh nghiệp nhỏ"),
    ("<b>put aside</b> / <b>pay</b> … <b>into</b>", "save regularly by putting a fixed sum into your bank account each month", "tiết kiệm đều đặn bằng cách gửi một khoản cố định vào tài khoản mỗi tháng"),
 ])
 + NOTE("<b>Exercise 36.1 – groups</b>: large amounts spent or received – <b>run through</b>, <b>gobble up</b>, <b>set back</b>, <b>clean out</b>, <b>roll in</b>; saving – <b>put by</b>, <b>put aside</b>, <b>pay in</b>; paying back a debt – <b>work off</b>, <b>square up</b>; earning from property – <b>rent out</b>. <b>36.4 adds</b>: <b>scrape by</b>, <b>chip in</b>, <b>rake in</b> (earn a lot), <b>cash up</b>, <b>stake</b> … <b>on</b>.",
        "<b>Bài 36.1 – nhóm</b>: tiêu hoặc nhận nhiều tiền – <b>run through</b>, <b>gobble up</b>, <b>set back</b>, <b>clean out</b>, <b>roll in</b>; tiết kiệm – <b>put by</b>, <b>put aside</b>, <b>pay in</b>; trả nợ – <b>work off</b>, <b>square up</b>; kiếm tiền từ nhà đất – <b>rent out</b>. <b>Bài 36.4 bổ sung</b>: <b>scrape by</b>, <b>chip in</b>, <b>rake in</b> (kiếm bộn tiền), <b>cash up</b>, <b>stake</b> … <b>on</b>.")
)
